param([string]$Configuration='Release')$ErrorActionPreference='Stop';function Step{param($Name,$Command)Write-Host "`n==> $Name";& $Command;if($LASTEXITCODE-ne 0){throw "$Name failed"};Write-Host "$Name PASS"};Step 'Domain Build' {dotnet build backend/src/Fraud/DeviceRisk.Domain/DeviceRisk.Domain.csproj -c $Configuration -nologo};Step 'Application Build' {dotnet build backend/src/Fraud/DeviceRisk.Application/DeviceRisk.Application.csproj -c $Configuration -nologo};Step 'Infrastructure Build' {dotnet build backend/src/Fraud/DeviceRisk.Infrastructure/DeviceRisk.Infrastructure.csproj -c $Configuration -nologo};Step 'API Build' {dotnet build backend/src/Fraud/DeviceRisk.Api/DeviceRisk.Api.csproj -c $Configuration -nologo};Step 'Scenario Runner' {dotnet run --project backend/tests/DeviceRisk.Scenarios/DeviceRisk.Scenarios.csproj -c $Configuration};Step 'Secret Scan' {powershell -NoProfile -ExecutionPolicy Bypass -File tools/release/scan-device-risk-secrets.ps1};Step 'Git Diff' {git diff --check};Write-Host 'AFW-DLV-0017.2 VALIDATION PASS';Write-Host 'Automatic blocking: NOT IMPLEMENTED';Write-Host 'Decision: READY FOR REVIEW'